**独立参考解答（非原书摘录）**

采用**不设头结点的单向循环链表**。每个结点保存 `id`、正整数 `password` 和 `next`；用 `tail` 指向最后一个结点，故首个报数者恒为 `tail->next`。输入前检查 `1 <= n <= 30`、初始 `m > 0`，以及每个密码均为正数。

~~~c
typedef struct Node {
    int id, password;
    struct Node *next;
} Node, *CList;

/* tail 是循环链表尾指针；建立时按编号 1..n 依次尾插。 */
void Joseph(CList *tail, int count, int m) {
    Node *pre = *tail;             // 当前报数起点的前驱
    while (count > 0) {
        int step = (m - 1) % count;
        while (step-- > 0) pre = pre->next;
        Node *out = pre->next;     // 从起点数 1，数到 m 的人
        输出(out->id);
        m = out->password;
        if (out == pre) {          // 仅余一个结点
            free(out);
            *tail = NULL;
            return;
        }
        pre->next = out->next;
        if (out == *tail) *tail = pre;
        free(out);
        --count;
        /* pre->next 正是出列者顺时针方向的下一人，下一轮从它报 1。 */
    }
}
~~~

循环不变式是：`pre->next` 为本轮的报数起点，循环链仍按尚未出列者的顺时针次序连接。移动 `(m-1) mod count` 步后，`pre->next` 恰为第 `m` 个报数者；删除后不变式仍成立。题给测试若以题面明确的首轮 `m=6` 运行，密码 `3,1,7,2,4,8,4` 的编号出列次序为 `6,1,4,7,2,3,5`。建表耗时 O(n)、空间 O(n)；模拟的最坏时间为 O(n²)，额外空间 O(1)。

**独立参考解答（非原书摘录）**

集合用**按字符升序、无重复结点的单链表**表示。读入时仅接纳 `a` 到 `z`；测试串中的数字和空格不属于题设元素，直接忽略。先用 `seen[26]` 去重，再按 `a` 至 `z` 尾插，得到有序链表，因而后续三个运算都可作归并扫描。

~~~c
typedef struct SNode { char ch; struct SNode *next; } SNode, *Set;

Set ReadSet(const char text[]) {
    bool seen[26] = {0};
    for (int i = 0; text[i] != 0; ++i)
        if ('a' <= text[i] && text[i] <= 'z') seen[text[i] - 'a'] = true;
    Set head = NULL, *tail = &head;
    for (int k = 0; k < 26; ++k) if (seen[k]) {
        *tail = NewNode('a' + k);
        tail = &(*tail)->next;
    }
    return head;
}

Set Union(Set p, Set q) {
    Set r = NULL, *tail = &r;
    while (p || q) {
        char x;
        if (!q || (p && p->ch < q->ch)) { x = p->ch; p = p->next; }
        else if (!p || q->ch < p->ch)   { x = q->ch; q = q->next; }
        else { x = p->ch; p = p->next; q = q->next; }
        *tail = NewNode(x); tail = &(*tail)->next;
    }
    return r;
}

Set Inter(Set p, Set q) {
    Set r = NULL, *tail = &r;
    while (p && q) {
        if (p->ch < q->ch) p = p->next;
        else if (q->ch < p->ch) q = q->next;
        else { *tail = NewNode(p->ch); tail = &(*tail)->next; p = p->next; q = q->next; }
    }
    return r;
}

Set Difference(Set p, Set q) {
    Set r = NULL, *tail = &r;
    while (p) {
        while (q && q->ch < p->ch) q = q->next;
        if (!q || p->ch < q->ch) { *tail = NewNode(p->ch); tail = &(*tail)->next; }
        else q = q->next;
        p = p->next;
    }
    return r;
}
~~~

归并时指针只前移，且每个输出字符都来自相应集合；相等分支只输出一次，故结果仍有序且无重复。三个运算均不改动两个操作数。若两表长度为 p、q，时间为 O(p+q)，结果空间为 O(p+q)。例如 `magazine` 与 `paper` 得到并集 `aegimnprz`、交集 `ae`、差集 `gimnz`；第二组测试按题设过滤非小写字符后得到 `adeinoprt`、`aeort`、`inp`。

**独立参考解答（非原书摘录）**

以**带头结点的循环双向链表**表示万进制长整数。头结点的 `tag` 保存带符号的结点数；`head->next` 是最高组，`head->prior` 是最低组，每个元素结点保存 `0..9999`。规范零唯一表示为一个值为 0 的结点且 `tag=1`。这样一组加法的最大中间值为 `9999+9999+1=19999`，不超过题设 16 位整型上界 32767。

~~~c
#define BASE 10000
typedef struct DNode {
    int group;                 // 头结点为带符号组数，元素结点为 0..9999
    struct DNode *prior, *next;
} DNode, *LongInt;

/* 解析时先读符号；去掉逗号后，首组 1..4 位、其余组恰 4 位，均为十进制数字。
   从左到右在 head 前尾插，所以 next 方向始终是高位到低位。 */
int CompareAbs(LongInt a, LongInt b);
LongInt AddAbs(LongInt a, LongInt b) {
    LongInt r = NewEmptyHead();
    DNode *p = a->prior, *q = b->prior;
    int carry = 0, cnt = 0;
    while (p != a || q != b || carry) {
        int s = carry + (p != a ? p->group : 0) + (q != b ? q->group : 0);
        InsertAfterHead(r, s % BASE); // 从低位向高位计算，前插保持高位在前
        carry = s / BASE; ++cnt;
        if (p != a) p = p->prior;
        if (q != b) q = q->prior;
    }
    r->group = cnt; return r;
}

/* 前提 |a| >= |b|；与 AddAbs 同样自尾向前，borrow 为 0 或 1。 */
LongInt SubAbs(LongInt a, LongInt b) {
    LongInt r = NewEmptyHead();
    DNode *p = a->prior, *q = b->prior;
    int borrow = 0, cnt = 0;
    while (p != a) {
        int s = p->group - borrow - (q != b ? q->group : 0);
        if (s < 0) { s += BASE; borrow = 1; } else borrow = 0;
        InsertAfterHead(r, s); ++cnt;
        p = p->prior; if (q != b) q = q->prior;
    }
    RemoveLeadingZeroGroups(r, &cnt);
    r->group = cnt; return r;
}

LongInt Add(LongInt a, LongInt b) {
    int sa = Sign(a), sb = Sign(b);
    LongInt r;
    if (sa == sb) { r = AddAbs(a, b); SetSign(r, sa); }
    else if (CompareAbs(a, b) >= 0) { r = SubAbs(a, b); SetSign(r, sa); }
    else { r = SubAbs(b, a); SetSign(r, sb); }
    NormalizeZero(r);
    return r;
}
~~~

`CompareAbs` 先比绝对组数，再自最高组逐组比较；`RemoveLeadingZeroGroups` 不删除唯一的零组。`Add` 只读两个操作数，结果另建链表，因此不会破坏输入。输出时先按 `tag` 的符号印负号，再从 `next` 至 `head` 印第一组和补足四位的后续组。应核验：`-2345,6789 + -7654,3211 = -1,0000,0000`，`-9999,9999 + 1,0000,0000,0000 = 9999,0000,0001`，以及相反数相加规范为 `0`。设两数分别有 p、q 组，比较、加减和输出均为 O(p+q)，结果空间 O(max(p,q))，且没有位数上限。

**独立参考解答（非原书摘录）**

用**带头结点的单链表**保存多项式。头结点 `terms` 为当前非零项数；每个元素结点为 `(coef, exp)`，并始终按指数严格降序排列。输入的 `n,c1,e1,...,cn,en` 不必预先有序：每读一项都经 `InsertTerm` 插入或与同指数项合并；系数绝对值不大于 `EPS` 的项立即删除，因此零多项式始终只有头结点且 `terms=0`。

~~~c
typedef struct Term { double coef; int exp; struct Term *next; } Term, *Poly;
const double EPS = 1e-10;

void InsertTerm(Poly h, double c, int e) {
    if (fabs(c) <= EPS) return;
    Term *pre = h, *p = h->next;
    while (p && p->exp > e) { pre = p; p = p->next; }
    if (p && p->exp == e) {
        p->coef += c;
        if (fabs(p->coef) <= EPS) { pre->next = p->next; free(p); --h->terms; }
    } else {
        Term *x = NewTerm(c, e); x->next = p; pre->next = x; ++h->terms;
    }
}

Poly AddOrSub(Poly a, Poly b, int signB) {
    Poly r = NewPolyHead();
    Term *p = a->next, *q = b->next;
    while (p || q) {
        if (!q || (p && p->exp > q->exp)) { InsertTerm(r, p->coef, p->exp); p = p->next; }
        else if (!p || q->exp > p->exp) { InsertTerm(r, signB * q->coef, q->exp); q = q->next; }
        else { InsertTerm(r, p->coef + signB * q->coef, p->exp); p = p->next; q = q->next; }
    }
    return r;
}
~~~

加法调用 `AddOrSub(a,b,+1)`，减法调用 `AddOrSub(a,b,-1)`；两个输入表只前移读取，结果另建。输出先印 `terms`，再依次印 `(coef,exp)`；数学格式输出时特别处理系数 ±1、常数项和符号。循环不变式是结果表已经包含指数高于当前两个指针的全部合并结果，且仍严格降序、无零项；故扫描结束即得到和或差。题给前三类例子分别可核验为 `-3.1x^11+11x^9+2x+7`、`-7.8x^15-1.2x^9+12x^-3-x`、`1+x+x^2+x^5`，相反多项式相加为零。建立表最坏 O(n²)，若输入已降序则 O(n)；加减时间 O(p+q)，结果空间 O(p+q)。

