**独立参考解答（非原书摘录）**

系统把相对稳定的航班时刻表存为按 `flightNo`（并可建立按 `destination` 的辅助索引）有序的顺序表。为避免同一航班不同日期混用，运行期以 `(flightNo,date)` 定位一个具体 `FlightInstance`；其中有 `capacity,available,seatClass[1..capacity],occupied[]`，以及按姓名有序的已订客户链表和 FIFO 链式候补队列。初始化时必须录入每座位的舱位等级；若业务不限制舱位，可把所有座位标为通用等级，不能凭空假定各等级配额。

~~~c
Status Book(FlightInstance *f, const char *name, int k, int grade) {
    if (!f || k <= 0 || grade < 1 || grade > 3 || NameExists(f,name)) return ERROR;
    int seats[MAX_REQUEST], got = 0;
    for (int s = 1; s <= f->capacity && got < k; ++s)
        if (!f->occupied[s] && Compatible(f->seatClass[s],grade)) seats[got++] = s;
    if (got != k) return FULL_OR_INSUFFICIENT;
    for (int i = 0; i < k; ++i) f->occupied[seats[i]] = true;
    InsertBookedByName(f, name, k, grade, seats);
    f->available -= k; 输出座位号(seats,k);
    return OK;
}

void Cancel(FlightInstance *f, const char *name) {
    Booked *b = FindBooked(f,name);
    if (!b) { 输出未找到; return; }
    ReleaseSeats(f,b); f->available += b->count; DeleteBooked(f,b);
    int once = QueueLength(f->wait);
    while (once-- > 0 && !QueueEmpty(f->wait)) {
        Waiter *w = DeQueue(&f->wait);
        if (AskStillWants(w) && Book(f,w->name,w->count,w->grade) == OK) FreeWaiter(w);
        else EnQueue(&f->wait,w);
    }
}
~~~

查询终点站时，遍历目的地索引并对每条记录用 `NextDate(today,weekday)` 算出最近飞行日，输出航班号、飞机号、星期、日期和该日期实例的余票。预订找不到航班、日期不是飞行日、票数非法、无同等级余座或余票不足时均不修改状态，交互地让客户改选或明确登记候补。退票只释放该客户实际座位，然后按候补入队次序询问一遍；未满足或放弃者的相对次序保留。

不变式：每个已订座位恰属于一个已订客户，`available + 已占座数 = capacity`，已订链表按姓名有序，候补队列 FIFO。查询为 O(r)，r 为同目的地航班数；已订客户查找 O(b)，分配/回收 O(capacity+k)，一次候补扫描 O(w)，空间 O(航班实例、已订客户和候补客户总数)。

**独立参考解答（非原书摘录）**

使用**链栈**作非递归深度优先搜索。将输入通路复制到 `maze[1..m][1..n]`，四周加值为 1 的障碍边框；`0` 为未访问通路、`1` 为障碍、`-1` 为已访问。方向编号固定为 1 东、2 南、3 西、4 北。栈帧 `(r,c,nextTry,outDir)` 表示当前点下一次从 `nextTry` 开始试探；`outDir` 是当前成功路径中从该点走向其子点的方向。入口和出口必须在矩阵内且均为 0。

~~~c
typedef struct PathNode {
    int r, c, nextTry, outDir;
    struct PathNode *next;
} PathNode, *LinkStack;
int dr[5] = {0,0,1,0,-1};
int dc[5] = {0,1,0,-1,0};

bool Solve(int m, int n, int sr, int sc, int er, int ec) {
    if (!Inside(sr,sc) || !Inside(er,ec) || maze[sr][sc] || maze[er][ec]) return false;
    Push(&S,(PathNode){sr,sc,1,0}); maze[sr][sc] = -1;
    if (sr == er && sc == ec) { PrintPath(S); return true; }
    while (!StackEmpty(S)) {
        Pop(&S,&p); bool advanced = false;
        for (int d = p.nextTry; d <= 4; ++d) {
            int nr = p.r + dr[d], nc = p.c + dc[d];
            if (maze[nr][nc] == 0) {
                p.nextTry = d + 1; p.outDir = d;
                Push(&S,p);                 // 保留回溯时的下一候选方向
                maze[nr][nc] = -1;
                Push(&S,(PathNode){nr,nc,1,0});
                if (nr == er && nc == ec) { PrintPath(S); return true; }
                advanced = true; break;
            }
        }
        if (!advanced) { /* p 的四方向均已试过，保持 -1 后回溯 */ }
    }
    return false;
}
~~~

`PrintPath` 将 S 逐个弹入辅助链栈，再从辅助栈弹出，故从入口到出口打印每个帧的 `(r,c,outDir)`；出口帧的 `outDir=0`，表示没有下一坐标。栈路径始终是不重复的已访问通路；某帧弹出且无合法方向时，所有由它出发的未访问分支已经尝试完毕。深度优先搜索因此要么到达出口，要么穷尽所有可达通路后正确报告无路。时间 O(mn)，栈和访问标记空间 O(mn)。

题面测试文字给出出口 `(8,9)`，配图却为 9 行 8 列且来源审计也提示 `(9,8)`；本算法不硬编码这一冲突，调用者按实际输入的 m、n 传入出口 `(m,n)`。若使用 9×8 图则传 `(9,8)`，若输入确为 8×9 则传 `(8,9)`。

