int StrCompare(HString s, HString t);             // 字典序，0 表示相等
Status Concat(HString *r, HString a, HString b);  // 长度 |a|+|b|
Status SubString(HString *r, HString s, int pos, int len) {
    if (pos < 1 || len < 0 || pos + len - 1 > s.length) return ERROR;
    return StrAssign(r, s.ch + pos - 1, len);
}
int Index(HString s, HString pat) {
    if (pat.length == 0) return ERROR;
    for (int i = 0; i + pat.length <= s.length; ++i)
        if (EqualAt(s,i,pat)) return i + 1;
    return 0;
}
Status Replace(HString *r, HString s, HString pat, HString repl) {
    if (pat.length == 0) return ERROR;
    Builder b; InitBuilder(&b);
    for (int i = 0; i < s.length; ) {
        if (i + pat.length <= s.length && EqualAt(s,i,pat)) { AppendString(&b,repl); i += pat.length; }
        else AppendChar(&b,s.ch[i++]);
    }
    return FinishBuilder(&b,r);
}
~~~

