        s->funcCodeLines = s->pendingHeaderLineCount;
        s->braceDepth = CandidateBraceDepth(s);
        if (s->braceDepth == 0) {
            out.closed = true; out.lines = s->funcCodeLines;
            out.kind = s->kind; ClearFunctionState(s);
